def fit(im, w, h):
    r = w / h; W, H = im.size
    if W / H > r:
        nw = int(H * r); im = im.crop(((W - nw) // 2, 0, (W - nw) // 2 + nw, H))
    else:
        nh = int(W / r); im = im.crop((0, (H - nh) // 2, W, (H - nh) // 2 + nh))
    return im.resize((w, h), Image.LANCZOS)
cities = {}
for it in ITEMS:
    os.makedirs(os.path.dirname(it["out"]), exist_ok=True)
    data = urllib.request.urlopen(it["url"], timeout=60).read()
    im = fit(Image.open(io.BytesIO(data)).convert("RGB"), *it["size"])
    for q in (76, 72, 68, 64):
        im.save(it["out"] + ".webp", "WEBP", quality=q, method=6)
        if os.path.getsize(it["out"] + ".webp") < 190000: break
    for q in (80, 76, 72, 68, 64):
        im.save(it["out"] + ".jpg", "JPEG", quality=q, optimize=True, progressive=True)
        if os.path.getsize(it["out"] + ".jpg") < 220000: break
    if "path" in it:
        rel = it["out"].replace("public", "", 1)
        cities[it["path"]] = {"src": rel + ".webp", "fallback": rel + ".jpg", "alt": it["alt"], "width": 1200, "height": 900}
    print("ok", it["out"])
os.makedirs("src/data", exist_ok=True)
json.dump(cities, open("src/data/city-hero-images.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
json.dump({it["out"].replace("public", "", 1) + ".jpg": it["alt"] for it in ITEMS if "path" not in it}, open("src/data/static-image-alts.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("done", len(ITEMS))
